use serde::Serialize;
use sha2::Sha256;
use std::{collections::HashMap, env, sync::{Arc, Mutex}, time::Duration};

type AppState = Arc<App>;
type Fields = HashMap<String, String>;
type AppResult<T> = Result<T, AppError>;

struct App {
    db: Mutex<Connection>,
    credentials: String,
    csrf: String,
}

#[derive(Debug)]
enum AppError {
    Database(rusqlite::Error),
    NotFound,
    Forbidden,
    BadRequest,
}
impl From<rusqlite::Error> for AppError {
    fn from(error: rusqlite::Error) -> Self { Self::Database(error) }
}
impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, title, message) = match self {
            Self::Database(error) => {
                eprintln!("Database error: {error}");
                (StatusCode::INTERNAL_SERVER_ERROR, "Something went wrong", "Please try again. Your saved quizzes are still here.")
            }
            Self::NotFound => (StatusCode::NOT_FOUND, "Page not found", "This quiz or question may have been deleted."),
            Self::Forbidden => (StatusCode::FORBIDDEN, "Please reload the form", "This form has expired. Reload the page and try again."),
            Self::BadRequest => (StatusCode::BAD_REQUEST, "Invalid request", "Please go back and try again."),
        };
        (status, Html(views::error_page(title, message))).into_response()
    }
}

#[derive(Debug, Serialize)]
struct Quiz { id: i64, title: String }
#[derive(Debug, Clone, Serialize)]
struct Choice { text: String, correct: bool }
#[derive(Debug, Serialize)]
struct Question { id: i64, text: String, active: bool, options: Vec<Choice> }
#[derive(Debug)]
struct QuestionInput { text: String, active: bool, options: Vec<Choice> }

impl QuestionInput {
    fn blank() -> Self {
        Self { text: String::new(), active: true, options: vec![Choice { text: String::new(), correct: false }; 4] }
    }
    fn from_fields(fields: &Fields) -> Self {
        let mut numbered: Vec<(usize, Choice)> = fields.iter().filter_map(|(key, text)| {
            let n = key.strip_prefix("option_")?.parse::<usize>().ok()?;
            Some((n, Choice { text: text.clone(), correct: fields.contains_key(&format!("correct_{n}")) }))
        }).collect();
        numbered.sort_by_key(|(n, _)| *n);
        Self {
            text: fields.get("question").cloned().unwrap_or_default(),
            active: fields.contains_key("active"),
            options: numbered.into_iter().map(|(_, choice)| choice).collect(),
        }
    }
    fn saved_options(&self) -> Vec<Choice> {
        self.options.iter().filter(|o| !o.text.trim().is_empty()).map(|o| Choice { text: o.text.trim().to_owned(), correct: o.correct }).collect()
    }
    fn errors(&self) -> Vec<&'static str> {
        let mut errors = Vec::new();
        let options = self.saved_options();
        if self.text.trim().is_empty() { errors.push("Question is required"); }
        if options.len() < 2 { errors.push("Add at least two options"); }
        if !options.iter().any(|o| o.correct) { errors.push("Mark at least one option as correct"); }
        errors
    }
}

fn initialize_db(db: &Connection) -> rusqlite::Result<()> {
    db.busy_timeout(Duration::from_secs(5))?;
    db.execute_batch("
        PRAGMA foreign_keys = ON;
        PRAGMA journal_mode = WAL;
        CREATE TABLE IF NOT EXISTS quizzes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL CHECK(length(trim(title)) > 0)
        );
        CREATE TABLE IF NOT EXISTS questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
            text TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0, 1)),
            position INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS questions_quiz_order ON questions(quiz_id, position, id);
        CREATE TABLE IF NOT EXISTS options (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            text TEXT NOT NULL,
            correct INTEGER NOT NULL CHECK(correct IN (0, 1)),
            position INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS options_question_order ON options(question_id, position, id);
    ")
}

fn get_quiz(db: &Connection, id: i64) -> AppResult<Quiz> {
    db.query_row("SELECT id, title FROM quizzes WHERE id=?", [id], |row| Ok(Quiz { id: row.get(0)?, title: row.get(1)? }))
        .optional()?.ok_or(AppError::NotFound)
}
fn get_questions(db: &Connection, quiz_id: i64) -> AppResult<Vec<Question>> {
    let mut stmt = db.prepare("SELECT id, text, active FROM questions WHERE quiz_id=? ORDER BY position, id")?;
    let mut questions = stmt.query_map([quiz_id], |row| Ok(Question { id: row.get(0)?, text: row.get(1)?, active: row.get(2)?, options: vec![] }))?
        .collect::<Result<Vec<_>, _>>()?;
    let mut stmt = db.prepare("SELECT text, correct FROM options WHERE question_id=? ORDER BY position, id")?;
    for question in &mut questions {
        question.options = stmt.query_map([question.id], |row| Ok(Choice { text: row.get(0)?, correct: row.get(1)? }))?
            .collect::<Result<Vec<_>, _>>()?;
    }
    Ok(questions)
}
fn get_question(db: &Connection, quiz_id: i64, question_id: i64) -> AppResult<Question> {
    get_questions(db, quiz_id)?.into_iter().find(|q| q.id == question_id).ok_or(AppError::NotFound)
}
fn verify_csrf(app: &App, fields: &Fields) -> AppResult<()> {
    if fields.get("csrf").is_some_and(|token| constant_eq(token.as_bytes(), app.csrf.as_bytes())) { Ok(()) } else { Err(AppError::Forbidden) }
}
fn constant_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() { return false; }
    a.iter().zip(b).fold(0u8, |diff, (a, b)| diff | (a ^ b)) == 0
}
fn quiz_url(id: i64) -> String { format!("/moderate/quizzes/{id}") }
fn question_url(quiz_id: i64, question_id: i64) -> String { format!("{}/questions/{question_id}", quiz_url(quiz_id)) }

async fn protect(State(app): State<AppState>, request: Request, next: Next) -> Response {
    let credentials = request.headers().get(header::AUTHORIZATION)
        .and_then(|h| h.to_str().ok()).and_then(|value| {
            let (scheme, encoded) = value.split_once(' ')?;
            if !scheme.eq_ignore_ascii_case("Basic") { return None; }
            STANDARD.decode(encoded.trim()).ok()
        });
    if !credentials.is_some_and(|supplied| constant_eq(&supplied, app.credentials.as_bytes())) {
        return (StatusCode::UNAUTHORIZED, [(header::WWW_AUTHENTICATE, "Basic realm=\"Quizzy moderator\", charset=\"UTF-8\""), (header::CACHE_CONTROL, "no-store")], "Moderator authentication required").into_response();
    }
    let mut response = next.run(request).await;
    response.headers_mut().insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    response
}

async fn security_headers(request: Request, next: Next) -> Response {
    let mut response = next.run(request).await;
    let headers = response.headers_mut();
    headers.insert(header::CONTENT_SECURITY_POLICY, HeaderValue::from_static("default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'"));
    headers.insert(header::X_CONTENT_TYPE_OPTIONS, HeaderValue::from_static("nosniff"));
    headers.insert(header::REFERRER_POLICY, HeaderValue::from_static("same-origin"));
    response
}

async fn list_quizzes(State(app): State<AppState>) -> AppResult<Html<String>> {
    let db = app.db.lock().unwrap();
    let mut stmt = db.prepare("SELECT q.id, q.title, COUNT(questions.id), COALESCE(SUM(questions.active), 0) FROM quizzes q LEFT JOIN questions ON questions.quiz_id=q.id GROUP BY q.id ORDER BY q.id DESC")?;
    let quizzes = stmt.query_map([], |row| Ok((Quiz { id: row.get(0)?, title: row.get(1)? }, row.get::<_, i64>(2)?, row.get::<_, i64>(3)?)))?
        .collect::<Result<Vec<_>, _>>()?;
    Ok(Html(views::quiz_list(&quizzes)))
}
async fn new_quiz(State(app): State<AppState>) -> Html<String> {
    Html(views::quiz_form(&app, None, "", &[]))
}
async fn create_quiz(State(app): State<AppState>, Form(fields): Form<Fields>) -> AppResult<Response> {
    verify_csrf(&app, &fields)?;
    let title = fields.get("title").map(String::as_str).unwrap_or_default();
    if title.trim().is_empty() {
        return Ok((StatusCode::UNPROCESSABLE_ENTITY, Html(views::quiz_form(&app, None, title, &["Title is required"]))).into_response());
    }
    let db = app.db.lock().unwrap();
    db.execute("INSERT INTO quizzes(title) VALUES (?)", [title.trim()])?;
    Ok(Redirect::to(&quiz_url(db.last_insert_rowid())).into_response())
}
async fn show_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> AppResult<Html<String>> {
    let db = app.db.lock().unwrap();
    Ok(Html(views::quiz_page(&app, &get_quiz(&db, id)?, &get_questions(&db, id)?)))
}
async fn edit_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> AppResult<Html<String>> {
    let quiz = get_quiz(&app.db.lock().unwrap(), id)?;
    Ok(Html(views::quiz_form(&app, Some(&quiz), &quiz.title, &[])))
}
async fn update_quiz(State(app): State<AppState>, Path(id): Path<i64>, Form(fields): Form<Fields>) -> AppResult<Response> {
    verify_csrf(&app, &fields)?;
    let db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, id)?;
    let title = fields.get("title").map(String::as_str).unwrap_or_default();
    if title.trim().is_empty() {
        return Ok((StatusCode::UNPROCESSABLE_ENTITY, Html(views::quiz_form(&app, Some(&quiz), title, &["Title is required"]))).into_response());
    }
    db.execute("UPDATE quizzes SET title=? WHERE id=?", params![title.trim(), id])?;
    Ok(Redirect::to(&quiz_url(id)).into_response())
}
async fn delete_quiz(State(app): State<AppState>, Path(id): Path<i64>, Form(fields): Form<Fields>) -> AppResult<Redirect> {
    verify_csrf(&app, &fields)?;
    if app.db.lock().unwrap().execute("DELETE FROM quizzes WHERE id=?", [id])? == 0 { return Err(AppError::NotFound); }
    Ok(Redirect::to("/moderate"))
}
async fn new_question(State(app): State<AppState>, Path(id): Path<i64>) -> AppResult<Html<String>> {
    let quiz = get_quiz(&app.db.lock().unwrap(), id)?;
    Ok(Html(views::question_form(&app, &quiz, None, &QuestionInput::blank(), &[])))
}
async fn edit_question(State(app): State<AppState>, Path((quiz_id, question_id)): Path<(i64, i64)>) -> AppResult<Html<String>> {
    let db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, quiz_id)?;
    let q = get_question(&db, quiz_id, question_id)?;
    let input = QuestionInput { text: q.text, active: q.active, options: q.options };
    Ok(Html(views::question_form(&app, &quiz, Some(question_id), &input, &[])))
}
fn save_question(app: &App, quiz_id: i64, question_id: Option<i64>, fields: Fields) -> AppResult<Response> {
    verify_csrf(app, &fields)?;
    let input = QuestionInput::from_fields(&fields);
    let mut db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, quiz_id)?;
    if let Some(id) = question_id { get_question(&db, quiz_id, id)?; }
    let errors = input.errors();
    if !errors.is_empty() {
        return Ok((StatusCode::UNPROCESSABLE_ENTITY, Html(views::question_form(app, &quiz, question_id, &input, &errors))).into_response());
    }
    let tx = db.transaction()?;
    let id = if let Some(id) = question_id {
        tx.execute("UPDATE questions SET text=?, active=? WHERE id=? AND quiz_id=?", params![input.text.trim(), input.active, id, quiz_id])?;
        tx.execute("DELETE FROM options WHERE question_id=?", [id])?;
        id
    } else {
        tx.execute("INSERT INTO questions(quiz_id,text,active,position) VALUES (?1,?2,?3,(SELECT COALESCE(MAX(position),0)+1 FROM questions WHERE quiz_id=?1))", params![quiz_id, input.text.trim(), input.active])?;
        tx.last_insert_rowid()
    };
    for (i, choice) in input.saved_options().iter().enumerate() {
        tx.execute("INSERT INTO options(question_id,text,correct,position) VALUES (?,?,?,?)", params![id, choice.text, choice.correct, i as i64])?;
    }
    tx.commit()?;
    Ok(Redirect::to(&quiz_url(quiz_id)).into_response())
}
async fn create_question(State(app): State<AppState>, Path(id): Path<i64>, Form(fields): Form<Fields>) -> AppResult<Response> {
    save_question(&app, id, None, fields)
}
async fn update_question(State(app): State<AppState>, Path((quiz_id, question_id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> AppResult<Response> {
    save_question(&app, quiz_id, Some(question_id), fields)
}
async fn delete_question(State(app): State<AppState>, Path((quiz_id, question_id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> AppResult<Redirect> {
    verify_csrf(&app, &fields)?;
    if app.db.lock().unwrap().execute("DELETE FROM questions WHERE id=? AND quiz_id=?", params![question_id, quiz_id])? == 0 { return Err(AppError::NotFound); }
    Ok(Redirect::to(&quiz_url(quiz_id)))
}
async fn toggle_question(State(app): State<AppState>, Path((quiz_id, question_id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> AppResult<Redirect> {
    verify_csrf(&app, &fields)?;
    if app.db.lock().unwrap().execute("UPDATE questions SET active=? WHERE id=? AND quiz_id=?", params![fields.contains_key("active"), question_id, quiz_id])? == 0 { return Err(AppError::NotFound); }
    Ok(Redirect::to(&format!("{}#question-{question_id}", quiz_url(quiz_id))))
}
async fn move_question(State(app): State<AppState>, Path((quiz_id, question_id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> AppResult<Redirect> {
    verify_csrf(&app, &fields)?;
    let direction = fields.get("direction").map(String::as_str).ok_or(AppError::BadRequest)?;
    if direction != "up" && direction != "down" { return Err(AppError::BadRequest); }
    let mut db = app.db.lock().unwrap();
    let tx = db.transaction()?;
    let mut ids = tx.prepare("SELECT id FROM questions WHERE quiz_id=? ORDER BY position, id")?.query_map([quiz_id], |row| row.get::<_, i64>(0))?.collect::<Result<Vec<_>, _>>()?;
    let index = ids.iter().position(|id| *id == question_id).ok_or(AppError::NotFound)?;
    let other = if direction == "up" { index.saturating_sub(1) } else { (index + 1).min(ids.len() - 1) };
    ids.swap(index, other);
    for (position, id) in ids.iter().enumerate() {
        tx.execute("UPDATE questions SET position=? WHERE id=?", params![position as i64, id])?;
    }
    tx.commit()?;
    Ok(Redirect::to(&format!("{}#question-{question_id}", quiz_url(quiz_id))))
}
async fn preview(State(app): State<AppState>, Path(id): Path<i64>) -> AppResult<Html<String>> {
    let db = app.db.lock().unwrap();
    let quiz = get_quiz(&db, id)?;
    let questions: Vec<_> = get_questions(&db, id)?.into_iter().filter(|q| q.active).collect();
    Ok(Html(views::preview(&quiz, &questions)))
}
async fn not_found() -> AppError { AppError::NotFound }
async fn asset(Path(name): Path<String>) -> Response {
    let (mime, bytes): (&str, &[u8]) = match name.as_str() {
        "quizzy.css" => ("text/css; charset=utf-8", include_bytes!("../assets/quizzy.css")),
        "app.css" => ("text/css; charset=utf-8", include_bytes!("../assets/app.css")),
        "app.js" => ("text/javascript; charset=utf-8", include_bytes!("../assets/app.js")),
        "Inter-latin.woff2" => ("font/woff2", include_bytes!("../assets/Inter-latin.woff2")),
        _ => return StatusCode::NOT_FOUND.into_response(),
    };
    ([(header::CONTENT_TYPE, mime), (header::CACHE_CONTROL, "public, max-age=3600")], bytes).into_response()
}

#[tokio::main]
async fn main() {
    let username = env::var("QUIZZY_MODERATOR_USERNAME").expect("QUIZZY_MODERATOR_USERNAME must be set");
    let password = env::var("QUIZZY_MODERATOR_PASSWORD").expect("QUIZZY_MODERATOR_PASSWORD must be set");
    let secret = env::var("SECRET_KEY_BASE").expect("SECRET_KEY_BASE must be set");
    assert!(!username.is_empty() && !password.is_empty() && !secret.is_empty(), "Credentials and SECRET_KEY_BASE must not be empty");
    assert!(!username.contains(':'), "Basic auth username cannot contain a colon");
    let credentials = format!("{username}:{password}");
    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes()).expect("HMAC key");
    mac.update(b"Quizzy moderator form token\0");
    mac.update(credentials.as_bytes());
    let csrf = STANDARD.encode(mac.finalize().into_bytes());
    std::fs::create_dir_all("storage").expect("Create storage directory");
    let db = Connection::open("storage/quizzy.sqlite3").expect("Open database");
    initialize_db(&db).expect("Initialize database");
    let app = Arc::new(App { db: Mutex::new(db), credentials, csrf });
    let moderator = Router::new()
        .route("/", get(list_quizzes))
        .route("/quizzes/new", get(new_quiz))
        .route("/quizzes", post(create_quiz))
        .route("/quizzes/{id}", get(show_quiz).post(update_quiz))
        .route("/quizzes/{id}/edit", get(edit_quiz))
        .route("/quizzes/{id}/delete", post(delete_quiz))
        .route("/quizzes/{id}/preview", get(preview))
        .route("/quizzes/{id}/questions/new", get(new_question))
        .route("/quizzes/{id}/questions", post(create_question))
        .route("/quizzes/{quiz_id}/questions/{question_id}", post(update_question))
        .route("/quizzes/{quiz_id}/questions/{question_id}/edit", get(edit_question))
        .route("/quizzes/{quiz_id}/questions/{question_id}/delete", post(delete_question))
        .route("/quizzes/{quiz_id}/questions/{question_id}/active", post(toggle_question))
        .route("/quizzes/{quiz_id}/questions/{question_id}/move", post(move_question))
        .fallback(not_found)
        .layer(middleware::from_fn_with_state(app.clone(), protect));
    let router = Router::new()
        .route("/", get(|| async { Redirect::to("/moderate") }))
        .route("/up", get(|| async { "OK" }))
        .route("/assets/{name}", get(asset))
        .route("/moderate", get(list_quizzes).layer(middleware::from_fn_with_state(app.clone(), protect)))
        .nest("/moderate", moderator)
        .fallback(not_found)
        .layer(middleware::from_fn(security_headers))
        .with_state(app);
    let port: u16 = env::var("PORT").unwrap_or_else(|_| "3000".into()).parse().expect("PORT must be a valid port");
    let listener = tokio::net::TcpListener::bind((std::net::Ipv4Addr::UNSPECIFIED, port)).await.expect("Bind HTTP listener");
    println!("Quizzy ready on http://0.0.0.0:{port}");
    axum::serve(listener, router).with_graceful_shutdown(async { let _ = tokio::signal::ctrl_c().await; }).await.expect("HTTP server");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn validation_skips_empty_options_even_when_correct() {
        let fields = Fields::from([
            ("question".into(), "  A question  ".into()),
            ("option_1".into(), "Alpha".into()),
            ("option_2".into(), "Beta".into()),
            ("option_3".into(), "   ".into()),
            ("correct_3".into(), "on".into()),
        ]);
        let input = QuestionInput::from_fields(&fields);
        assert_eq!(input.errors(), ["Mark at least one option as correct"]);
        assert_eq!(input.options[2].text, "   ");
        assert!(input.options[2].correct);
    }

    #[test]
    fn options_are_numeric_order_and_allow_several_correct() {
        let fields = Fields::from([
            ("question".into(), "Question".into()),
            ("option_10".into(), "Ten".into()),
            ("option_2".into(), " Two ".into()),
            ("correct_10".into(), "on".into()),
            ("correct_2".into(), "on".into()),
        ]);
        let input = QuestionInput::from_fields(&fields);
        assert!(input.errors().is_empty());
        assert_eq!(input.saved_options()[0].text, "Two");
        assert!(input.saved_options().iter().all(|o| o.correct));
        assert!(!input.active);
        assert!(QuestionInput::blank().active);
        assert_eq!(QuestionInput::blank().options.len(), 4);
    }

    #[test]
    fn empty_question_has_all_validation_messages() {
        assert_eq!(QuestionInput::blank().errors(), ["Question is required", "Add at least two options", "Mark at least one option as correct"]);
    }

    #[test]
    fn schema_and_cascades() {
        let db = Connection::open_in_memory().unwrap();
        initialize_db(&db).unwrap();
        initialize_db(&db).unwrap();
        db.execute("INSERT INTO quizzes(title) VALUES ('Test')", []).unwrap();
        db.execute("INSERT INTO questions(quiz_id,text,position) VALUES (1,'Question',0)", []).unwrap();
        db.execute("INSERT INTO options(question_id,text,correct,position) VALUES (1,'Yes',1,0)", []).unwrap();
        db.execute("DELETE FROM quizzes WHERE id=1", []).unwrap();
        assert_eq!(db.query_row("SELECT COUNT(*) FROM questions", [], |row| row.get::<_, i64>(0)).unwrap(), 0);
        assert_eq!(db.query_row("SELECT COUNT(*) FROM options", [], |row| row.get::<_, i64>(0)).unwrap(), 0);
    }
}
