pub fn quiz_list(quizzes: &[(Quiz, i64, i64)]) -> String {
    let mut html = String::from(r#"<div class="page-head"><div><h1>Quizzes</h1><p class="meta mt-2">A little preparation. A room full of participation.</p></div><a class="btn btn--pink" href="/moderate/quizzes/new">New quiz</a></div>"#);
    if quizzes.is_empty() {
        html.push_str(r#"<div class="empty"><h2>Your next talk starts here</h2><p>Create a quiz, add your questions, and try it out before you take the stage.</p></div>"#);
    } else {
        html.push_str(r#"<ul class="quiz-list list-reset" aria-label="Quizzes">"#);
        for (quiz, count, active) in quizzes {
            let noun = if *count == 1 { "question" } else { "questions" };
            let _ = write!(html, r#"<li class="card quiz-tile"><h3><a href="{}">{}</a></h3><div class="meta">{count} {noun} · {active} active</div></li>"#, quiz_url(quiz.id), escape(&quiz.title));
        }
        html.push_str("</ul>");
    }
    layout("Quizzes", &html)
}

pub fn quiz_form(app: &App, quiz: Option<&Quiz>, title: &str, messages: &[&str]) -> String {
    let heading = if quiz.is_some() { "Quiz settings" } else { "New quiz" };
    let action = quiz.map(|q| quiz_url(q.id)).unwrap_or_else(|| "/moderate/quizzes".into());
    let back = quiz.map(|q| quiz_url(q.id)).unwrap_or_else(|| "/moderate".into());
    let crumb = quiz.map(|q| q.title.as_str()).unwrap_or("All quizzes");
    let mut html = format!(r#"{}<div class="page-head"><h1>{heading}</h1></div><div class="card">
<form method="post" action="{action}">{}<div class="field"><label for="title">Title</label>
<input id="title" class="input" type="text" name="title" value="{}" required autofocus></div>{}
<div class="buttons"><button class="btn btn--pink" type="submit">Save quiz</button><a class="btn btn--ghost" href="{back}">Cancel</a></div></form></div>"#, breadcrumb(&back, crumb), token(app), escape(title), errors(messages));
    if quiz.is_some() {
        let _ = write!(html, r#"<section class="section danger-zone"><h2>Delete quiz</h2><p class="meta">This permanently deletes the quiz and all its questions.</p><form method="post" action="{action}/delete" data-confirm="Delete this quiz and all its questions? This cannot be undone.">{}<button class="btn btn--danger" type="submit">Delete quiz</button></form></section>"#, token(app));
    }
    layout(heading, &html)
}

pub fn quiz_page(app: &App, quiz: &Quiz, questions: &[Question]) -> String {
    let url = quiz_url(quiz.id);
    let title = escape(&quiz.title);
    let active = questions.iter().filter(|q| q.active).count();
    let total = questions.len();
    let csrf = token(app);
    let mut html = format!(r#"{}<div class="page-head"><div><h1>{title}</h1><div class="meta mt-2">{active} of {total} questions active · <a href="{url}/edit">Settings</a></div></div><div class="buttons"><a class="btn btn--ghost" href="{url}/preview">Preview</a></div></div>
<section class="section mt-0"><div class="section-head"><h2>Questions</h2><a class="btn" href="{url}/questions/new">Add question</a></div>"#, breadcrumb("/moderate", "All quizzes"));
    if questions.is_empty() {
        html.push_str(r#"<div class="empty"><h3>No questions yet</h3><p>Add your first question to get the conversation started.</p></div>"#);
    } else {
        html.push_str(r#"<ol class="list-reset questions" aria-label="Questions">"#);
        let mut number = 0;
        for (index, q) in questions.iter().enumerate() {
            let qurl = question_url(quiz.id, q.id);
            let inactive = if q.active { "" } else { " question-item--inactive" };
            let num = if q.active { number += 1; number.to_string() } else { "—".into() };
            let _ = write!(html, r#"<li class="card question-item{inactive}" id="question-{}"><div class="question-item__num" aria-hidden="true">{num}</div><div class="question-item__content"><div class="question-item__body">{}</div><ul class="question-item__options">"#, q.id, escape(&q.text));
            for (i, choice) in q.options.iter().enumerate() {
                let class = if choice.correct { "is-correct" } else { "" };
                let mark = if choice.correct { r#"<span class="sr-only"> (Correct)</span>"# } else { "" };
                let _ = write!(html, r#"<li class="{class}">{}. {}{mark}</li>"#, letter(i), escape(&choice.text));
            }
            let _ = write!(html, r#"</ul></div><div class="question-item__actions"><form class="buttons" method="post" action="{qurl}/move">{csrf}
<button class="btn btn--ghost btn--icon" type="submit" name="direction" value="up" aria-label="Move up" title="Move up"{}>↑</button>
<button class="btn btn--ghost btn--icon" type="submit" name="direction" value="down" aria-label="Move down" title="Move down"{}>↓</button></form>
<form method="post" action="{qurl}/active" class="active-form">{csrf}<label class="checkbox"><input type="checkbox" name="active"{}> Active</label><noscript><button class="btn btn--sm" type="submit">Save active status</button></noscript></form>
<div class="buttons"><a class="btn btn--sm" href="{qurl}/edit">Edit</a><form method="post" action="{qurl}/delete" data-confirm="Delete this question? This cannot be undone.">{csrf}<button class="btn btn--sm btn--danger" type="submit">Delete</button></form></div></div></li>"#, disabled(index == 0), disabled(index + 1 == total), checked(q.active));
        }
        html.push_str("</ol>");
    }
    html.push_str("</section>");
    layout(&quiz.title, &html)
}

pub fn question_form(app: &App, quiz: &Quiz, question_id: Option<i64>, input: &QuestionInput, messages: &[&str]) -> String {
    let title = if question_id.is_some() { "Edit question" } else { "New question" };
    let url = quiz_url(quiz.id);
    let action = question_id.map(|id| question_url(quiz.id, id)).unwrap_or_else(|| format!("{url}/questions"));
    let mut html = format!(r#"{}<div class="page-head"><h1>{title}</h1></div><div class="card"><form method="post" action="{action}" id="question-form">{}
<div class="field"><label for="question">Question</label><textarea class="input" rows="3" name="question" id="question" required>{}</textarea></div>
<div class="field"><span class="field-label" id="options-label">Options</span><span class="field-hint" id="options-hint">Mark the correct options, at least one. Empty rows are skipped.</span></div>
<div class="option-rows" id="option-rows" role="group" aria-labelledby="options-label" aria-describedby="options-hint">"#, breadcrumb(&url, &quiz.title), token(app), escape(&input.text));
    for (i, option) in input.options.iter().enumerate() {
        let n = i + 1;
        let _ = write!(html, r#"<div class="option-row"><input class="input" type="text" name="option_{n}" aria-label="Option {n}" placeholder="Option {n}" value="{}"><label class="checkbox"><input type="checkbox" name="correct_{n}" aria-label="Option {n} is correct"{}> Correct</label><button class="btn btn--danger btn--icon remove-option" type="button" aria-label="Remove option {n}" title="Remove option {n}">✕</button></div>"#, escape(&option.text), checked(option.correct));
    }
    let _ = write!(html, r#"</div><div class="buttons add-option"><button class="btn btn--ghost btn--sm" type="button" id="add-option"><span aria-hidden="true">+</span> Add option</button></div>
<div class="field"><label class="checkbox active-label"><input type="checkbox" name="active"{}> Active</label><span class="field-hint">Only active questions are played.</span></div>{}
<div class="buttons"><button class="btn btn--pink" type="submit">Save question</button><a class="btn btn--ghost" href="{url}">Cancel</a></div>
</form></div>"#, checked(input.active), errors(messages));
    layout(title, &html)
}

pub fn preview(quiz: &Quiz, questions: &[Question]) -> String {
    // JSON in a non-executable script tag still needs '<' escaped to prevent </script> injection.
    let data = serde_json::to_string(questions).expect("Serialize preview").replace('<', "\\u003c").replace('>', "\\u003e").replace('&', "\\u0026");
    document(&format!("Preview · {}", quiz.title), &format!(r#"<div class="preview-banner"><span>Preview · {}</span><a href="{}">← Back to quiz</a></div>
<div class="play preview-play"><header class="play__top"><a class="logo admin-header__logo play__logo" href="/moderate"><span class="logo__mark">?</span>Quizzy</a><span class="meta">Player preview</span></header>
<main class="play__body play__body--top" id="preview"><noscript><div class="errors">Enable JavaScript to try the preview.</div></noscript></main></div>
<script type="application/json" id="preview-data">{data}</script>"#, escape(&quiz.title), quiz_url(quiz.id)))
}

