fn checked(on: bool) -> &'static str {
    if on { " checked" } else { "" }
}
fn disabled(on: bool) -> &'static str {
    if on { " disabled" } else { "" }
}
fn errors(messages: &[&str]) -> String {
    if messages.is_empty() {
        return String::new();
    }
    let mut html = String::from(r#"<div class="errors" role="alert"><ul>"#);
    for message in messages {
        let _ = write!(html, "<li>{}</li>", escape(message));
    }
    html.push_str("</ul></div>");
    html
}
fn breadcrumb(url: &str, title: &str) -> String {
    format!(
        r#"<div class="breadcrumbs"><a href="{url}">← {}</a></div>"#,
        escape(title)
    )
}
fn letter(index: usize) -> String {
    // A…Z, AA…AZ… so extra rows never run out of labels.
    let mut n = index + 1;
    let mut chars = Vec::new();
    while n > 0 {
        n -= 1;
        chars.push((b'A' + (n % 26) as u8) as char);
        n /= 26;
    }
    chars.into_iter().rev().collect()
}

